void Solver::bump_var(int var, double coeff) {
    // Pre‑emptive overflow check: if the current activity is already close to the limit,
    // rescale all activities and the increment factor before adding the new bump.
    const double LIMIT = 1e100;
    if (activity[var] > LIMIT / var_inc) {
        const double SCALE = 1e-100;
        for (int i = 1; i <= vars; ++i) {
            activity[i] *= SCALE;
        }
        var_inc *= SCALE;
    }

    // Apply the bump.
    activity[var] += var_inc * coeff;

    // Update the VSIDS heap if the variable is present.
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}
